// --- Main Component ---



export type FanCardsProps = Record<string, any>;

const FanCards: React.FC<FanCardsProps> = ({
  backgroundColor = "#f0f0f0",
  transparentBackground = false,
  durationInSeconds = 8,
  cardSpread = 80,
  swayAmplitude = 25,
  arcRadius = 1200,
  card1Image,
  card2Image,
  card3Image,
  card4Image,
  card5Image,
  card6Image,
  card7Image,
}) => {
  useFontLoader(["Inter", "Playfair Display"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Merge images into card data
  const cards = React.useMemo(() => {
    const images = [
      card1Image,
      card2Image,
      card3Image,
      card4Image,
      card5Image,
      card6Image,
      card7Image,
    ];
    return DEFAULT_CARDS.map((card, i) => ({
      ...card,
      customImage: images[i],
    }));
  }, [
    card1Image,
    card2Image,
    card3Image,
    card4Image,
    card5Image,
    card6Image,
    card7Image,
  ]);

  // Animation: Center -> Left -> Right -> Center
  // 0 -> 20%: Sway Left
  // 20% -> 70%: Sway Right
  // 70% -> 100%: Back to Center
  const progress = interpolate(frame, [0, totalFrames], [0, 1]);

  const swayRotation = interpolate(
    frame,
    [0, totalFrames * 0.25, totalFrames * 0.65, totalFrames],
    [0, -swayAmplitude, swayAmplitude, 0],
    {
      easing: Easing.bezier(0.45, 0, 0.55, 1),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Card configuration
  const cardWidth = width * 0.22;
  const cardHeight = cardWidth * 1.5; // Aspect ratio ~2:3
  const cardCount = cards.length;

  // Calculate center index to balance the fan
  const centerIndex = (cardCount - 1) / 2;
  const anglePerCard = cardSpread / (cardCount - 1 || 1);

  // Pivot Point: Bottom Center + Radius offset
  // We simulate the arc by rotating from a very low pivot point
  const pivotY = height + arcRadius - cardHeight * 1.2;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Container for the swaying motion */}
      <AbsoluteFill
        style={{
          transformOrigin: `50% ${pivotY}px`,
          transform: `rotate(${swayRotation}deg)`,
          // We anchor the rotation at the calculated pivot point
        }}
      >
        {cards.map((card, i) => {
          // Calculate individual card rotation relative to the fan center
          const cardAngle = (i - centerIndex) * anglePerCard;

          // Stagger effect for entrance or subtle movement (optional, keeping it solid for now)
          // We can add a slight secondary motion to each card based on sway direction for inertia
          const inertia =
            interpolate(
              swayRotation,
              [-swayAmplitude, swayAmplitude],
              [-2, 2]
            ) *
            (i - centerIndex) *
            0.1; // Outer cards lag/lead slightly more

          return (
            <div
              key={card.id}
              style={{
                position: "absolute",
                left: (width - cardWidth) / 2,
                top: height - cardHeight - 150, // Position cards near bottom
                width: cardWidth,
                height: cardHeight,
                transformOrigin: `50% ${
                  pivotY - (height - cardHeight - 150)
                }px`,
                // Math: The transform origin needs to match the parent's effective pivot relative to the card
                // Simplification: Let's use the same large radius logic on each card
                transform: `rotate(${cardAngle + inertia}deg)`,
                zIndex: i,
              }}
            >
              <CardComponent
                data={card}
                width={cardWidth}
                height={cardHeight}
              />
            </div>
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default FanCards;